#!/usr/bin/env python3
"""
Run run_3dgrut_usdz_collision_pipeline.py for PLY files generated by
01_split_gaussian_ply_by_plane.py.

This script is only an orchestrator. It does not split PLYs and does not modify
the single-part 3DGRUT pipeline. It simply runs that pipeline once per input
part, with separate output paths.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import subprocess
import sys
from pathlib import Path


def run(cmd: list[str], env: dict[str, str]) -> None:
    print("\n[run]", " ".join(str(part) for part in cmd), flush=True)
    subprocess.run(cmd, check=True, env=env)


def default_pipeline_script() -> Path:
    return Path(__file__).resolve().parent / "run_3dgrut_usdz_collision_pipeline.py"


def load_parts_from_metadata(path: Path) -> tuple[Path, Path]:
    data = json.loads(path.read_text(encoding="utf-8"))
    try:
        return Path(data["negative_ply"]), Path(data["positive_ply"])
    except KeyError as exc:
        raise ValueError(f"{path} must contain negative_ply and positive_ply") from exc


def safe_label(label: str) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9_.-]+", "_", label.strip())
    cleaned = cleaned.strip("._-")
    if not cleaned:
        raise ValueError(f"Invalid empty part label from {label!r}")
    return cleaned


def parse_part_spec(spec: str) -> tuple[str, Path]:
    if "=" not in spec:
        raise argparse.ArgumentTypeError("Expected NAME=/path/to/file.ply")
    label, path = spec.split("=", 1)
    label = safe_label(label)
    if not path:
        raise argparse.ArgumentTypeError("PLY path is empty")
    return label, Path(path)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Run the 3DGRUT USDZ+collision pipeline for split PLY parts.")

    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--split-dir", help="Directory containing part_a.ply and part_b.ply.")
    source.add_argument("--metadata", help="split_metadata.json produced by 01_split_gaussian_ply_by_plane.py.")
    source.add_argument(
        "--part",
        action="append",
        type=parse_part_spec,
        metavar="NAME=PLY",
        help="Explicit named part. Can be repeated, e.g. --part door=/tmp/door.ply --part frame=/tmp/frame.ply.",
    )

    parser.add_argument("--part-a", default=None, help="Explicit part A PLY. Overrides --split-dir/--metadata value.")
    parser.add_argument("--part-b", default=None, help="Explicit part B PLY. Overrides --split-dir/--metadata value.")
    parser.add_argument("--negative-name", default="part_a")
    parser.add_argument("--positive-name", default="part_b")

    parser.add_argument("--out-dir", default=None, help="Defaults to split-dir/3dgrut_parts or metadata parent/3dgrut_parts.")
    parser.add_argument("--pipeline-script", default=None, help="Defaults to sibling run_3dgrut_usdz_collision_pipeline.py.")

    parser.add_argument("--filter-min-opacity", type=float, default=0.005)
    parser.add_argument("--filter-cluster-margin", type=float, default=0.12)
    parser.add_argument("--mesh-min-opacity", type=float, default=0.16)
    parser.add_argument("--simplify-target-faces", type=int, default=25000)
    parser.add_argument("--set-invisible", action="store_true")

    parser.add_argument("--cc", default="/usr/bin/gcc-12")
    parser.add_argument("--cxx", default="/usr/bin/g++-12")
    parser.add_argument("--cuda-host-cxx", default="/usr/bin/g++-12")
    return parser.parse_args()


def resolve_inputs(args: argparse.Namespace) -> tuple[list[tuple[str, Path]], Path]:
    base_dir: Path
    if args.part:
        parts = list(args.part)
        parent_strings = [str(path.resolve().parent) for _, path in parts]
        base_dir = Path(os.path.commonpath(parent_strings)) if parent_strings else Path.cwd()
    elif args.metadata:
        metadata_path = Path(args.metadata)
        part_a, part_b = load_parts_from_metadata(metadata_path)
        base_dir = metadata_path.parent
        parts = [("part_a", part_a), ("part_b", part_b)]
    else:
        base_dir = Path(args.split_dir)
        part_a = base_dir / f"{args.negative_name}.ply"
        part_b = base_dir / f"{args.positive_name}.ply"
        parts = [("part_a", part_a), ("part_b", part_b)]

    if args.part_a:
        parts = [(label, Path(args.part_a) if label == "part_a" else path) for label, path in parts]
    if args.part_b:
        parts = [(label, Path(args.part_b) if label == "part_b" else path) for label, path in parts]

    seen = set()
    resolved: list[tuple[str, Path]] = []
    for label, path in parts:
        label = safe_label(label)
        if label in seen:
            raise ValueError(f"Duplicate part label: {label}")
        seen.add(label)
        if not path.is_file():
            raise FileNotFoundError(path)
        resolved.append((label, path))

    if len(resolved) < 1:
        raise ValueError("At least one part is required")
    return resolved, base_dir


def run_part(
    label: str,
    input_ply: Path,
    out_root: Path,
    pipeline_script: Path,
    args: argparse.Namespace,
    env: dict[str, str],
) -> Path:
    part_dir = out_root / label
    part_dir.mkdir(parents=True, exist_ok=True)

    output_usdz = part_dir / f"{label}_with_collision.usdz"
    cmd = [
        sys.executable,
        str(pipeline_script),
        str(input_ply),
        "--out-dir",
        str(part_dir),
        "--filtered-ply",
        str(part_dir / f"{label}_filtered.ply"),
        "--visual-usdz",
        str(part_dir / f"{label}.usdz"),
        "--mesh-ply",
        str(part_dir / f"{label}_mesh.ply"),
        "--output-usdz",
        str(output_usdz),
        "--filter-min-opacity",
        str(args.filter_min_opacity),
        "--filter-cluster-margin",
        str(args.filter_cluster_margin),
        "--mesh-min-opacity",
        str(args.mesh_min_opacity),
        "--simplify-target-faces",
        str(args.simplify_target_faces),
        "--cc",
        args.cc,
        "--cxx",
        args.cxx,
        "--cuda-host-cxx",
        args.cuda_host_cxx,
    ]
    if args.set_invisible:
        cmd.append("--set-invisible")

    run(cmd, env)
    return output_usdz


def main() -> None:
    args = parse_args()
    parts, base_dir = resolve_inputs(args)

    out_root = Path(args.out_dir) if args.out_dir else base_dir / "3dgrut_parts"
    out_root.mkdir(parents=True, exist_ok=True)

    pipeline_script = Path(args.pipeline_script) if args.pipeline_script else default_pipeline_script()
    if not pipeline_script.is_file():
        raise FileNotFoundError(pipeline_script)

    env = os.environ.copy()
    env["CC"] = args.cc
    env["CXX"] = args.cxx
    env["CUDAHOSTCXX"] = args.cuda_host_cxx

    outputs: list[tuple[str, Path, Path]] = []
    for label, input_ply in parts:
        output_usdz = run_part(label, input_ply, out_root, pipeline_script, args, env)
        outputs.append((label, input_ply, output_usdz))

    summary_path = out_root / "split_parts_3dgrut_outputs.json"
    summary = {
        "parts": [
            {
                "name": label,
                "input_ply": str(input_ply),
                "output_usdz": str(output_usdz),
            }
            for label, input_ply, output_usdz in outputs
        ]
    }
    summary_path.write_text(json.dumps(summary, indent=2), encoding="utf-8")

    print("\n== Done ==")
    for label, input_ply, output_usdz in outputs:
        print(f"[{label}_input] {input_ply.resolve()}")
        print(f"[{label}_usdz]  {output_usdz.resolve()}")
    print(f"[summary_json]  {summary_path.resolve()}")


if __name__ == "__main__":
    main()
